<script setup lang="ts">
import{computed,ref}from'vue';import{useRouter}from'vue-router';import{state}from'../store';import Icon from'../components/Icon.vue';import ClubCard from'../components/ClubCard.vue';import ActivityCard from'../components/ActivityCard.vue';import{date}from'../utils'
const router=useRouter(),notice=ref(false),weekOffset=ref(0),selectedDay=ref('')
const upcoming=computed(()=>state.activities.filter(a=>new Date(a.endsAt).getTime()>Date.now()).sort((a,b)=>+new Date(a.startsAt)-+new Date(b.startsAt)))
const featured=computed(()=>upcoming.value.find(a=>a.featured)||upcoming.value[0])
const stats=computed(()=>[{label:'活跃社团',value:state.overview.clubCount,icon:'compass',sub:'发现属于你的兴趣圈',color:'green'},{label:'社团成员',value:state.overview.memberCount,icon:'users',sub:'与同频的伙伴相遇',color:'orange'},{label:'精彩活动',value:state.overview.activityCount,icon:'calendar',sub:`${state.overview.upcomingCount||0} 场活动正在等待你`,color:'purple'},{label:'共享器材',value:state.overview.equipmentCount,icon:'package',sub:'为每一次灵感提供支持',color:'blue'}])
const days=computed(()=>{const d=new Date();d.setDate(d.getDate()-((d.getDay()+6)%7)+weekOffset.value*7);return Array.from({length:7},(_,i)=>{const x=new Date(d);x.setDate(d.getDate()+i);return{day:x.getDate(),label:['一','二','三','四','五','六','日'][i],key:x.toLocaleDateString('sv-SE'),today:x.toDateString()===new Date().toDateString()}})})
const calendarItems=computed(()=>selectedDay.value?upcoming.value.filter(a=>new Date(a.startsAt).toLocaleDateString('sv-SE')===selectedDay.value):upcoming.value.slice(0,3))
const goClub=(c:{id:number})=>router.push({path:'/clubs',query:{club:c.id}}),goActivity=(a:{id:number})=>router.push({path:'/activities',query:{activity:a.id}})
</script>
<template><div class="page-content home-page"><div class="page-heading"><div><div class="eyebrow"><span class="mini-line"/> 让校园生活，彼此相连</div><h1>{{state.user?state.user.name+'，你好':'你好，校园探索家'}}<span class="greeting-dot">.</span></h1><p>有趣的灵魂，终会在这里相遇。开启今天的校园生活吧。</p></div><router-link to="/activities" class="outline-link"><Icon name="calendar" :size="17"/>查看活动日历<Icon name="arrowup" :size="16"/></router-link></div>
<div class="home-feature-grid"><section class="hero-card"><img src="/images/campus.jpg" class="hero-background" alt="阳光下的大学校园"><div class="hero-overlay"/><div class="hero-copy"><span class="hero-badge"><i/>每一种热爱，都有归属</span><h2>让热爱，<br>在校园发生<span>。</span></h2><p>探索社团、遇见伙伴、创造回忆。<br>你的大学生活，远比想象中精彩。</p><router-link to="/clubs" class="hero-cta">探索我的兴趣社团<Icon name="arrowup" :size="19"/></router-link></div><div class="hero-bottom"><div class="avatar-stack"><span>林</span><span>陈</span><span>周</span><span>李</span></div><span>和 {{state.overview.memberCount||0}} 位伙伴，一起奔赴热爱</span><span class="hero-counter">01 <i>/ 01</i></span></div><span class="hero-vertical">在这里，找到同频的人，也找到热爱的自己</span></section>
<section class="panel week-panel"><div class="section-top"><h3><Icon name="calendar" :size="18"/>校园日程</h3><span class="muted small">{{days[0]?.key.slice(0,7).replace('-',' 年 ')}} 月</span></div><div class="week-controls"><button class="icon-button" aria-label="上一周" @click="weekOffset--;selectedDay=''">‹</button><span>{{weekOffset===0?'这一周，值得期待':weekOffset>0?'未来的校园时光':'过去的校园时光'}}</span><button class="icon-button" aria-label="下一周" @click="weekOffset++;selectedDay=''">›</button></div><div class="week-days"><button v-for="d in days" :key="d.key" :class="{selected:selectedDay?selectedDay===d.key:d.today}" @click="selectedDay=selectedDay===d.key?'':d.key"><small>{{d.label}}</small><b>{{d.day}}</b><i v-if="upcoming.some(a=>new Date(a.startsAt).toLocaleDateString('sv-SE')===d.key)"/></button></div><div class="schedule-list"><button v-for="(a,i) in calendarItems.slice(0,3)" :key="a.id" class="schedule-item" @click="goActivity(a)"><span class="schedule-mark" :class="'mark-'+i"/><div><small>{{date(a.startsAt,true)}}</small><h4>{{a.title}}</h4><p><Icon name="pin" :size="12"/>{{a.location}}</p></div><Icon name="right" :size="15"/></button><p v-if="!calendarItems.length" class="calendar-empty">这一天暂时没有活动<br><router-link to="/activities">看看其他精彩活动 →</router-link></p></div><router-link to="/activities" class="calendar-all">查看全部活动<Icon name="arrow" :size="15"/></router-link></section></div>
<div class="stats-grid"><div v-for="stat in stats" :key="stat.label" class="stat-card"><div><span class="stat-label">{{stat.label}}</span><b>{{stat.value??'—'}}<small>{{stat.label==='精彩活动'?'场':stat.label==='共享器材'?'件':stat.label==='社团成员'?'人':'个'}}</small></b><p>{{stat.sub}}</p></div><span class="stat-icon" :class="stat.color"><Icon :name="stat.icon" :size="23"/></span></div></div>
<section class="home-section"><div class="section-heading"><div><h2>在这里，找到你的同频<span class="heading-badge">热门社团</span></h2><p>总有一个地方，盛得下你的奇思妙想。</p></div><router-link to="/clubs" class="text-link">发现全部社团<Icon name="arrow" :size="17"/></router-link></div><div class="club-grid home-clubs"><ClubCard v-for="c in state.clubs.slice(0,4)" :key="c.id" :club="c" @select="goClub"/></div></section>
<div class="home-bottom-grid"><section><div class="section-heading"><div><h2>下一站，精彩现场<span class="live-indicator"/></h2><p>走出宿舍，把今天过得不一样。</p></div><router-link to="/activities" class="text-link">全部活动<Icon name="arrow" :size="17"/></router-link></div><div class="activity-grid home-activities"><ActivityCard v-for="a in [featured,...upcoming.filter(x=>x.id!==featured?.id)].filter(Boolean).slice(0,2)" :key="a!.id" :activity="a!" @select="goActivity"/></div></section><section class="campus-board panel"><div class="section-top"><h3><Icon name="clipboard" :size="18"/>校园服务站</h3><span class="small muted">校园生活服务</span></div><button class="notice-card" @click="notice=true"><span class="notice-tag">温馨提示</span><h4>第一次参加社团活动？</h4><p>这份校园探索指南，帮你轻松开启新旅程。</p><span>阅读指南<Icon name="arrowup" :size="15"/></span></button><router-link to="/equipment" class="service-link"><span class="service-icon"><Icon name="package"/></span><span><b>器材共享，让灵感落地</b><small>在线申请 · 审核借用 · 便捷归还</small></span><Icon name="arrowup" :size="17"/></router-link><router-link to="/repairs" class="service-link"><span class="service-icon peach"><Icon name="wrench"/></span><span><b>有问题，我们来帮忙</b><small>在线报修 · 全程进度可查</small></span><Icon name="arrowup" :size="17"/></router-link></section></div>
<div class="bottom-banner"><Icon name="sparkles" :size="27"/><div><b>大学的精彩，从一次「我想试试」开始。</b><p>好奇心是最好的入场券，今天就出发。</p></div><router-link to="/clubs">寻找我的社团<Icon name="arrow" :size="17"/></router-link></div></div>
<el-dialog v-model="notice" title="校园探索指南" width="min(560px, 94vw)"><div class="guide-content"><h3>01 · 找到你感兴趣的社团</h3><p>进入「发现社团」浏览社团详情，填写加入理由并提交申请。管理员审核后，结果会显示在成员中心。</p><h3>02 · 为喜欢的活动留一个位置</h3><p>在活动详情中报名。报名后可在成员中心查看时间地点，活动开始前 30 分钟至结束期间，输入现场负责人提供的签到码完成签到。</p><h3>03 · 让校园服务帮你一把</h3><p>相机、帐篷、音箱等器材可以在线申请借用。遇到设备问题时，提交维修工单即可跟踪处理进度。</p></div><template #footer><el-button type="primary" @click="notice=false;router.push('/clubs')">开始探索</el-button></template></el-dialog></template>
